impl CliConfig {
    pub fn new() -> Self {
        Self {
            output: String::from("default"),
            verbose: false,
        }
    }

    /// Builds a config from command-line arguments (without the program name).
    /// \`--verbose\` / \`-v\` enables verbose output; other arguments are ignored.
    pub fn from_args<I, S>(args: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        let mut config = Self::new();
        for arg in args {
            if matches!(arg.as_ref(), "--verbose" | "-v") {
                config.verbose = true;
            }
        }
        config
    }
}

